func (v ConfigValue) Equal(o attr.Value) bool {
	other, ok := o.(ConfigValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Condition.Equal(other.Condition) {
		return false
	}

	if !v.Currency.Equal(other.Currency) {
		return false
	}

	if !v.DataSource.Equal(other.DataSource) {
		return false
	}

	if !v.EvaluateForEach.Equal(other.EvaluateForEach) {
		return false
	}

	if !v.IgnoreValuesRange.Equal(other.IgnoreValuesRange) {
		return false
	}

	if !v.Metric.Equal(other.Metric) {
		return false
	}

	if !v.Operator.Equal(other.Operator) {
		return false
	}

	if !v.Scopes.Equal(other.Scopes) {
		return false
	}

	if !v.TimeInterval.Equal(other.TimeInterval) {
		return false
	}

	if !v.Value.Equal(other.Value) {
		return false
	}

	return true
}

